// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address caller) public {
        if (caller == address(0)) caller = address(1);

        bool ok;
        bytes32 ret;
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32 v) {
            ok = true;
            ret = v;
        } catch {
            ok = false;
            ret = bytes32(0);
        }

        assertTrue(ok && ret != bytes32(0));
    }
}
